changeSet.sql:
ALTER TABLE stop_factors.stop_factor_rule
    ADD CONSTRAINT ck_stop_factor_rule_params_is_object CHECK (jsonb_typeof(params) = 'object');

-- every key of the params must be a param of the metric
DO $$
DECLARE
    undefined_params INTEGER;
BEGIN
    SELECT count(*) INTO undefined_params
    FROM stop_factors.stop_factor sf
    JOIN stop_factors.stop_factor_metric m ON m.id = sf.metric_id
    CROSS JOIN LATERAL jsonb_object_keys(sf.params) AS k(key)
    WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(m.params) AS d(definition)
                      WHERE d.definition ->> 'key' = k.key);
    IF undefined_params > 0 THEN
        RAISE EXCEPTION '% stop factor params are no param of their metric', undefined_params;
    END IF;
END $$;

INSERT INTO stop_factors.stop_factor_rule (id, created_date, stop_factor_id, name, order_number, params)
SELECT nextval('stop_factors.stop_factor_rule_id_generator'), now(), sf.id, sf.name, 1, jsonb_strip_nulls(sf.params)
FROM stop_factors.stop_factor sf
ORDER BY sf.id;

ALTER TABLE stop_factors.stop_factor
    DROP CONSTRAINT ck_stop_factor_params_is_object,
    DROP COLUMN params;

rollback.sql:
ALTER TABLE stop_factors.stop_factor ADD COLUMN params JSONB NOT NULL DEFAULT '{}';
UPDATE stop_factors.stop_factor sf
SET params = r.params
FROM stop_factors.stop_factor_rule r
WHERE r.stop_factor_id = sf.id AND r.order_number = 1;
ALTER TABLE stop_factors.stop_factor
    ADD CONSTRAINT ck_stop_factor_params_is_object CHECK (jsonb_typeof(params) = 'object');
DROP TABLE stop_factors.stop_factor_rule;
DROP SEQUENCE stop_factors.stop_factor_rule_id_generator;

changeSet.sql:
ALTER TABLE stop_factors.stop_factor_check ADD COLUMN rule_id BIGINT;
UPDATE stop_factors.stop_factor_check c
SET rule_id = r.id
FROM stop_factors.stop_factor_rule r
WHERE r.stop_factor_id = c.stop_factor_id;
ALTER TABLE stop_factors.stop_factor_check
    ALTER COLUMN rule_id SET NOT NULL,
    ADD CONSTRAINT fk_stop_factor_check_rule FOREIGN KEY (rule_id) REFERENCES stop_factors.stop_factor_rule (id),
    DROP CONSTRAINT fk_stop_factor_check_stop_factor,
    DROP COLUMN stop_factor_id;
CREATE INDEX idx_stop_factor_check_rule_id ON stop_factors.stop_factor_check (rule_id);

