    DROP COLUMN rule_id;
CREATE INDEX idx_stop_factor_check_stop_factor_id ON stop_factors.stop_factor_check (stop_factor_id);

changeSet.sql:
DO $$
DECLARE
    family         RECORD;
    member_roots   BIGINT[];
    group_id       BIGINT;
    group_order    INT;
    group_versions BIGINT[];
    bounds         TIMESTAMP[];
    epoch_count    INT;
    epoch_no          INT;
    epoch_start    TIMESTAMP;
    epoch_end      TIMESTAMP;
    version_id     BIGINT;
    version_active BOOLEAN;
    member_row         RECORD;
    member_version RECORD;
    member_rule    BIGINT;
    rule_position       INT;
    moved_rules    BIGINT[];
    copy_id        BIGINT;
BEGIN
    CREATE TEMP TABLE rule_of_version ON COMMIT DROP AS
    SELECT stop_factor_id AS version_id, id AS rule_id FROM stop_factors.stop_factor_rule;
    -- the member versions as they were, read while the rows are changed
    CREATE TEMP TABLE family_version (id BIGINT, root BIGINT, version_number INT, valid_from TIMESTAMP,
                                      valid_to TIMESTAMP, is_active BOOLEAN, root_order INT) ON COMMIT DROP;

    FOR family IN SELECT * FROM (VALUES
            ('RESTRUCTURING_COUNT', 'Количество реструктуризаций'),
            ('OVERDUE_BUCKET_COUNT', 'Количество непрерывной просроченной задолженности')) AS f(calculator, name)
    LOOP
        SELECT array_agg(sf.id ORDER BY sf.id) INTO member_roots
        FROM stop_factors.stop_factor sf
        JOIN stop_factors.stop_factor_metric m ON m.id = sf.metric_id
        WHERE m.calculator = family.calculator AND sf.root_id IS NULL AND sf.created_by = 'migration';
        CONTINUE WHEN member_roots IS NULL OR array_length(member_roots, 1) < 2;
        group_id := member_roots[1];
        DELETE FROM family_version;
        INSERT INTO family_version
        SELECT sf.id, COALESCE(sf.root_id, sf.id), sf.version_number, sf.valid_from, sf.valid_to, sf.is_active, root.order_number
        FROM stop_factors.stop_factor sf
        JOIN stop_factors.stop_factor root ON root.id = COALESCE(sf.root_id, sf.id)
        WHERE COALESCE(sf.root_id, sf.id) = ANY (member_roots);

        IF EXISTS (SELECT 1 FROM stop_factors.stop_factor sf
                   WHERE COALESCE(sf.root_id, sf.id) = ANY (member_roots)
                     AND (sf.segment IS NOT NULL
                          OR EXISTS (SELECT 1 FROM stop_factors.stop_factor_product p WHERE p.stop_factor_id = sf.id))) THEN
            RAISE EXCEPTION 'Stop factors % have products or segments, they cannot be grouped', member_roots;
        END IF;

        SELECT COALESCE(min(order_number) FILTER (WHERE is_active), min(order_number)) INTO group_order
        FROM stop_factors.stop_factor WHERE id = ANY (member_roots);
        SELECT array_agg(DISTINCT valid_to ORDER BY valid_to) INTO bounds FROM family_version WHERE valid_to IS NOT NULL;
        epoch_count := COALESCE(array_length(bounds, 1), 0) + 1;

        -- the orders inside the group are set below; negative ones keep uq_stop_factor_rule_order meanwhile
        UPDATE stop_factors.stop_factor_rule SET order_number = -id
        WHERE stop_factor_id IN (SELECT id FROM stop_factors.stop_factor WHERE COALESCE(root_id, id) = ANY (member_roots));

        group_versions := '{}';
        moved_rules := '{}';
        FOR epoch_no IN 1..epoch_count LOOP
            epoch_start := CASE WHEN epoch_no = 1
                                THEN (SELECT min(valid_from) FROM family_version)
                                ELSE bounds[epoch_no - 1] END;
            epoch_end := CASE WHEN epoch_no < epoch_count THEN bounds[epoch_no] END;

            IF epoch_no = 1 THEN
                version_id := group_id;
                UPDATE stop_factors.stop_factor
                SET name = family.name, description = NULL, order_number = group_order, valid_from = epoch_start,
                    valid_to = epoch_end, updated_date = now()
                WHERE id = group_id;
            ELSE
                version_id := nextval('stop_factors.stop_factor_id_generator');
                INSERT INTO stop_factors.stop_factor (id, created_date, name, description, is_active, order_number, root_id,
                                                      version_number, valid_from, valid_to, change_reason, created_by, metric_id)
                SELECT version_id, now(), family.name, NULL, false, group_order, group_id, epoch_no, epoch_start, epoch_end,
                       COALESCE((SELECT max(sf.change_reason) FROM stop_factors.stop_factor sf
                                 JOIN family_version fv ON fv.id = sf.id WHERE fv.valid_from = epoch_start),
                                'Объединение стоп-факторов в правила'),
                       'migration', metric_id
                FROM stop_factors.stop_factor WHERE id = group_id;
            END IF;
            group_versions := group_versions || version_id;

            version_active := false;
            rule_position := 0;
            -- members in their display order, the inactive ones (order 0) last
            FOR member_row IN
                SELECT root, root_order FROM family_version GROUP BY root, root_order
                ORDER BY (root_order = 0), root_order, root
            LOOP
                member_version := NULL;
                SELECT * INTO member_version FROM family_version fv
                WHERE fv.root = member_row.root
                  AND fv.valid_from < COALESCE(epoch_end, 'infinity')
                  AND COALESCE(fv.valid_to, 'infinity') >= COALESCE(epoch_end, 'infinity')
                ORDER BY fv.version_number LIMIT 1;
                CONTINUE WHEN member_version.id IS NULL;

                rule_position := rule_position + 1;
                version_active := version_active OR member_version.is_active;
                SELECT rule_id INTO member_rule FROM rule_of_version WHERE rule_of_version.version_id = member_version.id;
                IF NOT member_rule = ANY (moved_rules) THEN
                    UPDATE stop_factors.stop_factor_rule
                    SET stop_factor_id = version_id, order_number = rule_position, is_active = member_version.is_active,
                        updated_date = now()
                    WHERE id = member_rule;
                    moved_rules := moved_rules || member_rule;
                ELSE
                    copy_id := nextval('stop_factors.stop_factor_rule_id_generator');
                    INSERT INTO stop_factors.stop_factor_rule (id, created_date, stop_factor_id, name, order_number, is_active, params)
                    SELECT copy_id, now(), version_id, name, rule_position, member_version.is_active, params
                    FROM stop_factors.stop_factor_rule WHERE id = member_rule;
                    INSERT INTO stop_factors.stop_factor_condition (id, created_date, rule_id, value, value_type, result, operator, value_to)
                    SELECT nextval('stop_factors.stop_factor_condition_id_generator'), now(), copy_id,
                           value, value_type, result, operator, value_to
                    FROM stop_factors.stop_factor_condition WHERE rule_id = member_rule;
                END IF;
            END LOOP;
            UPDATE stop_factors.stop_factor SET is_active = version_active WHERE id = version_id;
        END LOOP;

        -- the member_row rows have no rules any more; a rule left behind (and its checks) stops the migration here
        DELETE FROM stop_factors.stop_factor
        WHERE root_id IS NOT NULL AND COALESCE(root_id, id) = ANY (member_roots) AND NOT id = ANY (group_versions);
        DELETE FROM stop_factors.stop_factor
        WHERE root_id IS NULL AND id = ANY (member_roots) AND NOT id = ANY (group_versions);
    END LOOP;
END $$;

DO $$ DECLARE metric stop_factors.stop_factor_metric%ROWTYPE; next_order INT; seg RECORD; r RECORD; sf_id BIGINT; new_rule_id BIGINT; BEGIN SELECT * INTO metric FROM stop_factors.stop_factor_metric WHERE calculator = 'OVERDUE_BUCKET_COUNT' ORDER BY id LIMIT 1; IF metric.id IS NULL THEN RAISE EXCEPTION 'Metric OVERDUE_BUCKET_COUNT not found'; END IF; SELECT COALESCE(MAX(order_number), 0) INTO next_order FROM stop_factors.stop_factor WHERE valid_to IS NULL;
FOR seg IN SELECT * FROM (VALUES ('RETAIL', 'Розница и ИФЦ'), ('MSB', 'МСБ')) AS s(segment, description) LOOP sf_id := nextval('stop_factors.stop_factor_id_generator'); next_order := next_order + 1; INSERT INTO stop_factors.stop_factor (id, created_date, name, description, is_active, order_number, version_number, valid_from, change_reason, created_by, metric_id, segment) VALUES (sf_id, now(), metric.title, seg.description, true, next_order, 1, now(), 'Правила по просрочкам 2026', 'migration', metric.id, seg.segment);
FOR r IN SELECT * FROM (VALUES -- months overdue days UNDERWRITER REJECTED ('RETAIL', 1, 1, 3, 1, 10::int, NULL::int, 5), ('RETAIL', 2, 1, 3, 11, 20, 1, 2), ('RETAIL', 3, 1, 3, 21, NULL, NULL, 0), ('RETAIL', 4, 4, 6, 1, 10, NULL, 5), ('RETAIL', 5, 4, 6, 11, 20, 1, 2), ('RETAIL', 6, 4, 6, 21, NULL, NULL, 0), ('RETAIL', 7, 7, 12, 6, 10, 5, 8), ('RETAIL', 8, 7, 12, 11, 20, 0, 1), ('RETAIL', 9, 7, 12, 21, NULL, NULL, 0), ('RETAIL', 10, 13, 24, 11, 20, 7, 10), ('RETAIL', 11, 13, 24, 21, 30, 0, 1), ('RETAIL', 12, 13, 24, 31, NULL, NULL, 0), ('RETAIL', 13, 25, 36, 31, 60, 0, 1), ('RETAIL', 14, 25, 36, 61, NULL, NULL, 0), ('MSB', 1, 1, 3, 1, 10, 5, 10), ('MSB', 2, 1, 3, 11, 20, 1, 2), ('MSB', 3, 1, 3, 21, NULL, NULL, 0), ('MSB', 4, 4, 6, 1, 10, 5, 10), ('MSB', 5, 4, 6, 11, 20, 1, 2), ('MSB', 6, 4, 6, 21, NULL, NULL, 0), ('MSB', 7, 7, 12, 11, 20, 7, 10), ('MSB', 8, 7, 12, 21, 30, 0, 1), ('MSB', 9, 7, 12, 31, NULL, NULL, 0), ('MSB', 10, 13, 24, 11, 20, 7, 10), ('MSB', 11, 13, 24, 21, 30, 0, 1), ('MSB', 12, 13, 24, 31, NULL, NULL, 0), ('MSB', 13, 25, 36, 31, 60, 0, 1), ('MSB', 14, 25, 36, 61, NULL, NULL, 0) ) AS t(segment, n, period_from, period_to, min_days, max_days, underwriter_above, rejected_above) WHERE t.segment = seg.segment ORDER BY n LOOP new_rule_id := nextval('stop_factors.stop_factor_rule_id_generator'); INSERT INTO stop_factors.stop_factor_rule (id, created_date, stop_factor_id, name, order_number, params) VALUES (new_rule_id, now(), sf_id, format('Количество непрерывной просроченной задолженности по основному долгу и/или процентам с %s по %s месяц, где максимальная просрочка >= %s', r.period_from, r.period_to, r.min_days) || CASE WHEN r.max_days IS NOT NULL THEN ' и <= ' || r.max_days ELSE '' END, r.n, jsonb_strip_nulls(jsonb_build_object('periodFromMonth', r.period_from, 'periodToMonth', r.period_to, 'minOverdueDays', r.min_days, 'maxOverdueDays', r.max_days)));
INSERT INTO stop_factors.stop_factor_condition (id, created_date, rule_id, value, value_type, result, operator) VALUES (nextval('stop_factors.stop_factor_condition_id_generator'), now(), new_rule_id, r.rejected_above::text, 'INTEGER', 'REJECTED', 'GT'); IF r.underwriter_above IS NOT NULL THEN INSERT INTO stop_factors.stop_factor_condition (id, created_date, rule_id, value, value_type, result, operator, value_to) VALUES (nextval('stop_factors.stop_factor_condition_id_generator'), now(), new_rule_id, r.underwriter_above::text, 'INTEGER', 'UNDERWRITER', 'RANGE', r.rejected_above::text); END IF; END LOOP; END LOOP; END $$;

rollback.sql:
DELETE FROM stop_factors.stop_factor_condition WHERE rule_id IN (
    SELECT r.id FROM stop_factors.stop_factor_rule r JOIN stop_factors.stop_factor sf ON sf.id = r.stop_factor_id
    WHERE sf.created_by = 'migration' AND sf.change_reason = 'Правила по просрочкам 2026');
DELETE FROM stop_factors.stop_factor_rule WHERE stop_factor_id IN (
    SELECT id FROM stop_factors.stop_factor
    WHERE created_by = 'migration' AND change_reason = 'Правила по просрочкам 2026');
DELETE FROM stop_factors.stop_factor
WHERE created_by = 'migration' AND change_reason = 'Правила по просрочкам 2026';
